WITH FilteredStoreSales AS (SELECT *, CASE WHEN units >= 45 THEN 'High' WHEN units >= 13 THEN 'Medium' ELSE 'Low' END AS units_band FROM store_sales WHERE product_id IN (2, 4, 5) AND units <= 26), agg AS (SELECT DATE_FORMAT(sale_date, 'yyyy-MM') AS sale_month, store_id, AVG(units) AS avg_units, SUM(revenue) AS total_revenue FROM FilteredStoreSales GROUP BY DATE_FORMAT(sale_date, 'yyyy-MM'), store_id) SELECT * FROM agg WHERE avg_units > 27 ORDER BY avg_units DESC, sale_month ASC, store_id ASC LIMIT 50;
